import{_ as e,o as i,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"UC 07 — Subscription (UC-90 → UC-96)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/07-subscription.md","filePath":"ba/use-cases/07-subscription.md"}'),n={name:"ba/use-cases/07-subscription.md"};function o(l,t,s,c,d,g){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="uc-07-—-subscription-uc-90-→-uc-96" tabindex="-1">UC 07 — Subscription (UC-90 → UC-96) <a class="header-anchor" href="#uc-07-—-subscription-uc-90-→-uc-96" aria-label="Permalink to &quot;UC 07 — Subscription (UC-90 → UC-96)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../08-subscription-billing.html">08-subscription-billing.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code> &gt; <strong>Lưu ý:</strong> Plan gắn với User/Owner (tầng Agency), không mua riêng theo từng Workspace.</p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-90</td><td>Upgrade Plan</td><td>USER</td><td>3.9.1</td></tr><tr><td>UC-91</td><td>Downgrade/Cancel Plan</td><td>OWNER</td><td>3.9.2</td></tr><tr><td>UC-92</td><td>Make Payment via PayOS</td><td>USER</td><td>3.9.3</td></tr><tr><td>UC-93</td><td>View Invoice History</td><td>OWNER</td><td>3.9.4</td></tr><tr><td>UC-94</td><td>View AI Credit Tracking</td><td>CREATOR/OWNER</td><td>3.9.5</td></tr><tr><td>UC-95</td><td>Buy AI Credit</td><td>CREATOR/OWNER</td><td>3.9.6</td></tr><tr><td>UC-96</td><td>Set AI Credit Limit</td><td>OWNER</td><td>3.9.7</td></tr></tbody></table><hr><h2 id="uc-90-—-upgrade-plan" tabindex="-1">UC-90 — Upgrade Plan <a class="header-anchor" href="#uc-90-—-upgrade-plan" aria-label="Permalink to &quot;UC-90 — Upgrade Plan&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> Upgrade from the Basic plan to Pro/Enterprise for more Workspaces, AI credits, and advanced features.</li><li><strong>Precondition:</strong> User currently on a lower-tier plan (default new user = Basic).</li><li><strong>Main Flow:</strong><ol><li>USER selects a higher tier (Pro/Enterprise).</li><li>System proceeds to payment (UC-92).</li><li>On successful payment, plan tier upgraded — limits (max Workspaces, AI credit) increased.</li></ol></li></ul><h2 id="uc-91-—-downgrade-cancel-plan" tabindex="-1">UC-91 — Downgrade/Cancel Plan <a class="header-anchor" href="#uc-91-—-downgrade-cancel-plan" aria-label="Permalink to &quot;UC-91 — Downgrade/Cancel Plan&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Cancel the current plan when no longer needed.</li><li><strong>Precondition:</strong> OWNER has an active paid plan.</li><li><strong>Main Flow:</strong><ol><li>OWNER requests downgrade/cancel.</li><li>System schedules the change (e.g., effective at next billing cycle) or applies immediately per policy.</li></ol></li></ul><h2 id="uc-92-—-make-payment-via-payos" tabindex="-1">UC-92 — Make Payment via PayOS <a class="header-anchor" href="#uc-92-—-make-payment-via-payos" aria-label="Permalink to &quot;UC-92 — Make Payment via PayOS&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> Create a payment transaction for plan upgrades or credit purchases, ensuring ACID compliance.</li><li><strong>Precondition:</strong> User initiated an upgrade (UC-90) or credit purchase (UC-95).</li><li><strong>Main Flow:</strong><ol><li>USER confirms payment details.</li><li>System creates a Transaction and calls PayOS.</li><li>On confirmed payment, System commits the Transaction atomically (ACID) and applies the plan/credit change.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Payment fails/cancelled → Transaction rolled back, no plan/credit change applied.</li></ul></li></ul><h2 id="uc-93-—-view-invoice-history" tabindex="-1">UC-93 — View Invoice History <a class="header-anchor" href="#uc-93-—-view-invoice-history" aria-label="Permalink to &quot;UC-93 — View Invoice History&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> View the account&#39;s transaction history.</li><li><strong>Precondition:</strong> At least one completed Transaction.</li><li><strong>Main Flow:</strong><ol><li>OWNER opens Invoice History.</li><li>System lists past transactions (plan upgrades, credit purchases).</li></ol></li></ul><h2 id="uc-94-—-view-ai-credit-tracking" tabindex="-1">UC-94 — View AI Credit Tracking <a class="header-anchor" href="#uc-94-—-view-ai-credit-tracking" aria-label="Permalink to &quot;UC-94 — View AI Credit Tracking&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/OWNER</li><li><strong>Description:</strong> Monitor the amount of AI credit used within the current month.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>CREATOR views their own usage; OWNER views Agency-wide usage across all Creators.</li><li>System displays credit consumed this month (image/content/video generation).</li></ol></li></ul><h2 id="uc-95-—-buy-ai-credit" tabindex="-1">UC-95 — Buy AI Credit <a class="header-anchor" href="#uc-95-—-buy-ai-credit" aria-label="Permalink to &quot;UC-95 — Buy AI Credit&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/OWNER</li><li><strong>Description:</strong> Purchase additional AI credit.</li><li><strong>Precondition:</strong> Existing plan credit allowance exhausted.</li><li><strong>Main Flow:</strong><ol><li>OWNER initiates a credit purchase (goes through UC-92 payment flow).</li><li>System adds purchased credit to the Agency&#39;s balance.</li></ol></li><li><strong>Business Rule:</strong> Only OWNER can buy credit — Creator cannot purchase credit for themself directly.</li></ul><h2 id="uc-96-—-set-ai-credit-limit" tabindex="-1">UC-96 — Set AI Credit Limit <a class="header-anchor" href="#uc-96-—-set-ai-credit-limit" aria-label="Permalink to &quot;UC-96 — Set AI Credit Limit&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Set a spending limit on AI credit usage for Creators.</li><li><strong>Precondition:</strong> OWNER of the Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER selects a Creator, sets a per-Creator credit usage cap.</li><li>System enforces the cap — Creator&#39;s AI actions blocked once their individual limit is reached, even if the Agency&#39;s shared pool still has balance.</li></ol></li></ul>',19)])])}const p=e(n,[["render",o]]);export{h as __pageData,p as default};
